$(document).ready(function(){$("#menu").click(function(){$(this).toggleClass("fa-times");$(".navbar").toggleClass("nav-toggle")});$(window).on("scroll load",function(){$("#menu").removeClass("fa-times");$(".navbar").removeClass("nav-toggle");if(window.scrollY>60){document.querySelector("#scroll-top").classList.add("active")}else{document.querySelector("#scroll-top").classList.remove("active")}});$(".navbar ul li a").click(function(){$("#menu").removeClass("fa-times");$(".navbar").removeClass("nav-toggle")})});document.addEventListener("visibilitychange",function(){if(document.visibilityState==="visible"){document.title="Collins Otieno | Full-Stack Developer & Electrical Engineer";$("#favicon").attr("href","./assets/images/favicon.png")}else{document.title="Come Back To Portfolio";$("#favicon").attr("href","./assets/images/favhand.png")}});var typed=new Typed(".typing-text",{strings:["web development","electrical engineering","solar installations","full stack development","Laravel development","PHP programming"],loop:true,typeSpeed:50,backSpeed:25,backDelay:500});async function fetchData(type="skills"){let response;try{response=await fetch(type+".json")}catch(error){console.error("Error fetching data:",error);return}const data=await response.json();return data}function showSkills(skills){let skillsContainer=document.getElementById("skillsContainer");let skillHTML="";skills.forEach(skill=>{skillHTML+=`<div class="bar"><div class="info"><span>${skill.name}</span></div></div>`});skillsContainer.innerHTML=skillHTML}fetchData().then(data=>{showSkills(data)});ScrollReveal({reset:true,distance:"80px",duration:2000,delay:200});ScrollReveal().reveal(".home .content, .heading",{origin:"top"});ScrollReveal().reveal(".home .image, .about .content, .skills .container, .education .box, .work .box, .experience .timeline, .contact .container",{origin:"bottom"});ScrollReveal().reveal(".home .content h1, .about .content .tag",{origin:"left"});ScrollReveal().reveal(".home .content p, .about .content .desc",{origin:"right"});VanillaTilt.init(document.querySelectorAll(".tilt"),{max:15});document.addEventListener("DOMContentLoaded",function(){const lazyImages=document.querySelectorAll("img[loading='lazy']");const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.src;img.classList.remove("lazy");observer.unobserve(img)}})});lazyImages.forEach(img=>{imageObserver.observe(img)})});